using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class B3Align {public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("B3 saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();int n=0;foreach(var q in JArray.Parse(File.ReadAllText(r+"/SourceAssets/B3_FullFloor/alignment.json"))){var t=ts.Single(t=>t.name==(string)q["name"]);t.localPosition=new Vector3((float)q["position"][0],(float)q["position"][1],(float)q["position"][2]);t.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);PrefabUtility.RecordPrefabInstancePropertyModifications(t);n++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{aligned=n};}}
